         AND political_organizations_count = 107 
         AND constituencies_count = 4123 
         AND states_count = 36 
         AND constituency_lineage_count = 126 
         AND provenance_records_count = 2456 
        THEN 'PASS' 
        ELSE 'FAIL' 
      END
    ),
    'verdict', (
